  "紫微|田宅": {"줄": [{"밝기": null,"갈래": "사건","글": "집과 땅을 당신의 손으로 마련하고, 마련한 것이 넉넉하게 불어나요.","규칙": ["K2-0720"]},{"밝기": null,"갈래": "사건","글": "집과 땅을 마련했다가 잃고, 잃었다가 다시 마련해요. (자미두수전서 「有置有去」)","규칙": ["K2-0721"]},{"밝기": null,"갈래": "사건","글": "물려받은 집과 땅은 지키지 못하고 떠나요. (자미두수전서 「退祖」)","규칙": ["K2-0722"]},{"밝기": null,"갈래": "사건","글": "이미 이루어진 집안 재산이 있어요. 당신이 처음부터 마련하지 않아도 물려받을 집과 땅이 있어요.","규칙": ["K2-0723"]}]},
  "天機|田宅": {"줄": [{"밝기": null,"갈래": "사건","글": "물려받은 집과 땅은 지키지 못하고, 대신 당신의 손으로 새로 마련해요. (자미두수전서 「退祖新创置」)","규칙": ["K2-0724"]},{"밝기": null,"갈래": "사건","글": "논밭 · 땅이 있어요.","규칙": ["K2-0725"]},{"밝기": null,"갈래": "사건","글": "물려받은 재산을 지키지 못하고, 처음엔 크다가 뒤로 갈수록 작아져요.","규칙": ["K2-0726"]},{"밝기": null,"갈래": "사건","글": "당신의 손으로 마련하는 집과 땅이 있고, 나이 들어서 부유해져요.","규칙": ["K2-0727"]},{"밝기": null,"갈래": "사건","글": "당신의 손으로 마련한 집과 땅이 넉넉하게 불어나요.","규칙": ["K2-0728"]}]},
  "太陽|田宅": {"줄": [{"밝기": null,"갈래": "사건","글": "태양과 태음이 이 칸에 함께 있는 짜임(일월조벽)은 옛 책이 귀하게 꼽은 짜임 가운데 하나예요. (자미두수전서 「日月照璧」)","규칙": ["K1-일월조벽"]},{"밝기": null,"갈래": "사건","글": "할아버지 · 아버지 대에서 내려오는 덕을 입어요 — 윗대가 마련해 둔 것이 당신에게 닿아요.","규칙": ["K1-태양전택"]},{"밝기": "廟","갈래": "사건","글": "물려받은 집과 땅이 있어요. 처음엔 넉넉하다가 뒤로 갈수록 고르지 않아요.","규칙": ["K2-0729"]},{"밝기": null,"갈래": "사건","글": "땅이 많아요.","규칙": ["K2-0730"]},{"밝기": null,"갈래": "사건","글": "집과 땅이 넉넉하게 불어나요.","규칙": ["K2-0731"]},{"밝기": null,"갈래": "사건","글": "물려받은 집과 땅은 지키지 못하지만, 땅이 아예 없지는 않아요.","규칙": ["K2-0732"]},{"밝기": "落陷","갈래": "사건","글": "집과 땅이 전혀 없어요. (자미두수전서 「全无」)","규칙": ["K2-0733"]}]},
  "武曲|田宅": {"줄": [{"밝기": "廟 · 旺","갈래": "사건","글": "할아버지 · 아버지가 일군 큰 재산을 물려받아요.","규칙": ["K2-0734"]},{"밝기": "落陷","갈래": "사건","글": "처음 가진 집과 땅은 지키지 못해요. 한 번 잃은 뒤에야 다시 마련해요.","규칙": ["K2-0735"]},{"밝기": null,"갈래": "사건","글": "집안 재산이 흩어지고, 있어도 오래가지 않아요. (자미두수전서 「破荡家产」)","규칙": ["K2-0736"]},{"밝기": null,"갈래": "사건","글": "먼저 잃고, 그 뒤에야 집과 땅이 생겨요.","규칙": ["K2-0737"]},{"밝기": null,"갈래": "특성","글": "집과 땅을 갖고 싶어 하지 않아요.","규칙": ["K2-0738"]},{"밝기": null,"갈래": "사건","글": "이미 이루어진 집안 재산을 지켜요.","규칙": ["K2-0739"]},{"밝기": null,"갈래": "사건","글": "집과 땅은 늦게 마련해요.","규칙": ["K2-0740"]},{"밝기": null,"갈래": "사건","글": "땅이 넉넉하게 불어나 아주 좋아요. (자미두수전서 「极美」)","규칙": ["K2-0741"]},{"밝기": null,"갈래": "사건","글": "집과 땅이 들어왔다 나갔다 해요.","규칙": ["K2-0742"]}]},
  "天同|田宅": {"줄": [{"밝기": null,"갈래": "사건","글": "처음엔 적다가 뒤로 갈수록 많아져요. 당신의 손으로 마련한 집과 땅이 크게 불어나요.","규칙": ["K2-0743"]},{"밝기": null,"갈래": "사건","글": "땅이 적어요.","규칙": ["K2-0744"]},{"밝기": null,"갈래": "사건","글": "크게 부유해요. (자미두수전서 「大富」)","규칙": ["K2-0745"]},{"밝기": null,"갈래": "사건","글": "먼저 잃고 뒤에 다시 늘려요.","규칙": ["K2-0746"]}]},
